UPDATE public.wa_campaign_lead_jobs SET context = context || jsonb_build_object('historical_authorized',true,'historical_until','2026-11-26T00:04:00Z') WHERE campaign_id='d8280a2b-4f27-43e0-a8bd-e1e841a302f4' AND created_at < '2026-11-26T00:04:00Z' AND status IN ('waiting_window','awaiting_category') AND selected_category IS NULL;
WITH candidates AS MATERIALIZED (SELECT inbox_id FROM public.wa_campaign_lead_jobs WHERE campaign_id='d8280a2b-4f27-43e0-a8bd-e1e841a302f4' AND context->>'historical_authorized'='true' AND status IN ('waiting_window','awaiting_category') ORDER BY created_at LIMIT 3), removed AS (DELETE FROM public.wa_campaign_reply_dispatch d USING candidates c WHERE d.inbox_id=c.inbox_id AND d.status IN ('done','failed') RETURNING d.inbox_id) INSERT INTO public.wa_campaign_reply_dispatch(inbox_id) SELECT inbox_id FROM candidates WHERE (SELECT count(*) FROM removed)>=0 ON CONFLICT(inbox_id) DO NOTHING;